export async function seedCurated() {
  await ensureKnownNames()
  let ok = 0
  let dup = 0
  let fail = 0
  for (const raw of CURATED) {
    raw.cat = CATEGORY_MAP[raw.n] ?? 'Uncategorized'
    const entry = validateEntry(raw, raw.cat)
    if ('error' in entry) {
      console.log(`  ✗ ${raw.n}: ${entry.error}`)
      fail++
      continue
    }
    const res = await insertEntry(entry, { status: 'verified', dataQuality: 'well_documented' })
    if (res.ok) {
      ok++
      console.log(`  ✓ ${entry.name}`)
    } else {
      if (res.reason?.startsWith('duplicate')) dup++
      else { fail++; console.log(`  ✗ ${entry.name}: ${res.reason}`) }
    }
    await sleep(20)
  }
  console.log(`Curated seed: ${ok} inserted, ${dup} duplicates skipped, ${fail} failed`)
}
